import{_ as e,o as a,c as r,a0 as n}from"./chunks/framework.D7EjqxMK.js";const c=JSON.parse('{"title":"其他框架速览","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/02_核心框架/07_其他框架速览.md","filePath":"06-agent/02_核心框架/07_其他框架速览.md"}'),o={name:"06-agent/02_核心框架/07_其他框架速览.md"};function d(l,t,i,g,h,s){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="其他框架速览" tabindex="-1">其他框架速览 <a class="header-anchor" href="#其他框架速览" aria-label="Permalink to &quot;其他框架速览&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块二 · 02_核心框架 · 第 7 节 <strong>难度</strong>：⭐⭐ | <strong>前置知识</strong>：其他框架</p></blockquote><hr><h2 id="_1-crewai-—-多-agent-团队" tabindex="-1">1. CrewAI — 多 Agent 团队 <a class="header-anchor" href="#_1-crewai-—-多-agent-团队" aria-label="Permalink to &quot;1. CrewAI — 多 Agent 团队&quot;">​</a></h2><p>CrewAI 将多个 Agent 组织成&quot;团队&quot;，每个 Agent 有角色、目标和工具。原生支持 MCP Server。</p><ul><li><strong>文档</strong>：<a href="https://docs.crewai.com/" target="_blank" rel="noreferrer">CrewAI</a></li><li><strong>MCP 集成</strong>：<a href="https://docs.crewai.org.cn/en/mcp/dsl-integration" target="_blank" rel="noreferrer">CrewAI MCP DSL</a></li></ul><h2 id="_2-autogen-—-多-agent-对话-已与微软-agent-framework-合并" tabindex="-1">2. AutoGen — 多 Agent 对话（已与微软 Agent Framework 合并） <a class="header-anchor" href="#_2-autogen-—-多-agent-对话-已与微软-agent-framework-合并" aria-label="Permalink to &quot;2. AutoGen — 多 Agent 对话（已与微软 Agent Framework 合并）&quot;">​</a></h2><p>Microsoft AutoGen 通过 Agent 对话完成任务，原生支持 MCP。</p><ul><li><strong>文档</strong>：<a href="https://microsoft.github.io/autogen/" target="_blank" rel="noreferrer">AutoGen</a></li><li><strong>AutoGen + MCP</strong>：<a href="https://llmmultiagent.com/blogs/autogen_mcp_blog" target="_blank" rel="noreferrer">AutoGen与MCP文章</a></li></ul><h2 id="_3-metagpt-—-多-agent-软件工程" tabindex="-1">3. MetaGPT — 多 Agent 软件工程 <a class="header-anchor" href="#_3-metagpt-—-多-agent-软件工程" aria-label="Permalink to &quot;3. MetaGPT — 多 Agent 软件工程&quot;">​</a></h2><p>用多 Agent 模拟软件公司的完整工作流。</p><ul><li><strong>论文</strong>：<a href="https://arxiv.org/abs/2308.00352" target="_blank" rel="noreferrer">MetaGPT 论文</a></li></ul><h2 id="_4-phidata-—-本地优先-agent" tabindex="-1">4. Phidata — 本地优先 Agent <a class="header-anchor" href="#_4-phidata-—-本地优先-agent" aria-label="Permalink to &quot;4. Phidata — 本地优先 Agent&quot;">​</a></h2><p>开源 Agent 框架，强调本地运行和自定义。</p><ul><li><strong>GitHub</strong>：<a href="https://github.com/phidatahq/phidata" target="_blank" rel="noreferrer">Phidata</a></li></ul><hr><h2 id="框架选型对比" tabindex="-1">框架选型对比 <a class="header-anchor" href="#框架选型对比" aria-label="Permalink to &quot;框架选型对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>框架</th><th>范式</th><th>核心优势</th><th>适合</th><th>来源</th></tr></thead><tbody><tr><td>OpenAI Agents SDK</td><td>轻量 Agent</td><td>官方 SDK</td><td>快速开发</td><td><a href="https://github.com/openai/openai-agents-python" target="_blank" rel="noreferrer">GitHub</a></td></tr><tr><td>LangGraph</td><td>有向图</td><td>复杂工作流</td><td>生产级</td><td><a href="https://langchain-ai.github.io/langgraph/" target="_blank" rel="noreferrer">LangChain</a></td></tr><tr><td>LangChain</td><td>链式</td><td>生态大</td><td>简单链式</td><td><a href="https://python.langchain.com/" target="_blank" rel="noreferrer">LangChain</a></td></tr><tr><td>LlamaIndex</td><td>检索优先</td><td>RAG</td><td>知识库</td><td><a href="https://docs.llamaindex.ai/" target="_blank" rel="noreferrer">LlamaIndex</a></td></tr><tr><td>CrewAI</td><td>多Agent团队</td><td>角色分工</td><td>团队协作</td><td><a href="https://docs.crewai.com/" target="_blank" rel="noreferrer">CrewAI</a></td></tr><tr><td>AutoGen</td><td>Agent对话</td><td>对话协作</td><td>多 Agent</td><td><a href="https://microsoft.github.io/autogen/" target="_blank" rel="noreferrer">AutoGen</a></td></tr><tr><td>DSPy</td><td>程序化提示</td><td>自动优化</td><td>提示工程</td><td><a href="https://dspy.ai/" target="_blank" rel="noreferrer">DSPy</a></td></tr><tr><td>Pydantic AI</td><td>类型安全</td><td>类型安全</td><td>Python</td><td><a href="https://ai.pydantic.dev/" target="_blank" rel="noreferrer">Pydantic AI</a></td></tr><tr><td>MetaGPT</td><td>软件工程</td><td>完整开发流</td><td>代码生成</td><td><a href="https://arxiv.org/abs/2308.00352" target="_blank" rel="noreferrer">arXiv</a></td></tr></tbody></table><hr><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li><a href="https://nicklaunches.com/blog/ai-agent-frameworks-comparison-2025/" target="_blank" rel="noreferrer">Comparing 5 AI Agent Frameworks (Nick Launches)</a></li><li><a href="https://www.digitalapplied.com/blog/openai-agents-sdk-vs-langgraph-vs-crewai-matrix-2026" target="_blank" rel="noreferrer">OpenAI Agents SDK vs LangGraph vs CrewAI: 2026 Matrix</a></li><li><a href="https://softcery.com/lab/top-14-ai-agent-frameworks-of-2025-a-founders-guide-to-building-smarter-systems" target="_blank" rel="noreferrer">14 AI Agent Frameworks Compared (Softcery)</a></li><li><a href="https://speakeasyapi.dev/blog/ai-agent-framework-comparison" target="_blank" rel="noreferrer">Choosing an agent framework (Speakeasy)</a></li><li><a href="https://udit.co/blog/raw/ai-agent-frameworks-compared-2026" target="_blank" rel="noreferrer">AI Agent Frameworks Compared (udit.co)</a></li></ul>',21)])])}const f=e(o,[["render",d]]);export{c as __pageData,f as default};
